export type NfeCreateData = {
    body: {
        items: Array<ProductEmitItem>;
        /**
         * Destinatário (dest). Informe `taxId` (CPF/CNPJ) ou, no exterior, `foreignId` (idEstrangeiro) com
         * `address.country` fora do Brasil — nunca os dois. Os campos fiscais valem só para esta nota e
         * prevalecem sobre o cadastro do cliente (IE informada, ISENTO ou não contribuinte).
         *
         */
        recipient: {
            /**
             * CPF ou CNPJ (obrigatório sem foreignId)
             */
            taxId?: string;
            /**
             * idEstrangeiro (passaporte/ID fiscal estrangeiro). Exige address.country ≠ Brasil; sem IE/SUFRAMA/IM (indIEDest 9)
             */
            foreignId?: string;
            name: string;
            email?: string;
            /**
             * enderDest/fone (6 a 14 dígitos; máscara é removida)
             */
            phone?: string;
            /**
             * IE do destinatário (2 a 14 dígitos; máscara é removida) ou "ISENTO" (equivale a ieIndicator 2)
             */
            stateRegistration?: string;
            /**
             * indIEDest: 1|taxpayer (exige IE numérica), 2|exempt (sai sem a tag IE), 9|nonTaxpayer (sem IE; indFinal 1).
             * Omitido: segue a IE informada ou a do cadastro.
             *
             */
            ieIndicator?: 1 | 2 | 9 | 'taxpayer' | 'exempt' | 'nonTaxpayer' | '1' | '2' | '9';
            /**
             * dest/ISUF — inscrição SUFRAMA (8 ou 9 dígitos)
             */
            suframa?: string;
            /**
             * dest/IM (NF-e conjugada)
             */
            municipalRegistration?: string;
            address?: NfeAddress;
        };
        /**
         * Desconto da nota (venda), rateado pelos itens em vDesc sobre o valor líquido e somado ao `items[].discount`.
         * Não pode passar do total dos itens menos os descontos dos itens, nem ser usado junto com `totals.discount` (422).
         *
         */
        discount?: number;
        /**
         * Dados de transporte inline (opcional). `freightModality` é obrigatório
         * quando `carrier` é enviado; `noShipping` com `carrier` retorna 422 (`VALIDATION_ERROR`).
         *
         */
        transport?: {
            /**
             * Também aceita os códigos SEFAZ 0/1/2/3/4/9 como alias
             */
            freightModality?: 'bySender' | 'byRecipient' | 'byThirdParties' | 'ownBySender' | 'ownByRecipient' | 'noShipping';
            /**
             * Valor do frete; compõe o total quando por conta do emitente.
             * Sem `freightModality`, um valor maior que zero assume frete por conta do remetente (CIF, modFrete 0).
             *
             */
            value?: number;
            carrier?: TransportCarrier;
            /**
             * Volumes (`transp/vol`); exige `freightModality`. Aceita também os nomes do leiaute (qVol, esp, marca, nVol, pesoL, pesoB)
             */
            volumes?: Array<{
                /**
                 * qVol
                 */
                quantity?: number;
                /**
                 * esp
                 */
                species?: string;
                /**
                 * marca
                 */
                brand?: string;
                /**
                 * nVol
                 */
                numbering?: string;
                /**
                 * pesoL (kg)
                 */
                netWeight?: number;
                /**
                 * pesoB (kg)
                 */
                grossWeight?: number;
                /**
                 * lacres/nLacre. Alias `lacres` (lista de textos ou de `{ nLacre }`)
                 */
                seals?: Array<string>;
            }>;
            /**
             * retTransp — retenção do ICMS do serviço de transporte
             */
            withholding?: {
                /**
                 * vServ
                 */
                serviceAmount: number;
                /**
                 * vBCRet
                 */
                baseAmount: number;
                /**
                 * pICMSRet
                 */
                rate: number;
                /**
                 * vICMSRet
                 */
                amount: number;
                cfop: string;
                /**
                 * cMunFG (IBGE)
                 */
                cityCode: string;
            };
            /**
             * reboque — { plate, state?, rntc? }. Exclusivo com wagon/ferry
             */
            trailers?: Array<{
                [key: string]: unknown;
            }>;
            /**
             * vagao (ferroviário). Exclusivo com veículo/reboque/balsa
             */
            wagon?: string;
            /**
             * balsa (aquaviário). Exclusivo com veículo/reboque/vagão
             */
            ferry?: string;
        };
        /**
         * Atalho de forma de pagamento (um `detPag` com o valor total da nota).
         * pix=17, credit_card=03, debit_card=04, cash=01, bank_slip=15, bank_transfer=18, no_payment=90, other=99.
         * Com `payments[]`, os pagamentos detalhados prevalecem.
         *
         */
        paymentMethod?: 'credit_card' | 'debit_card' | 'pix' | 'bank_transfer' | 'cash' | 'bank_slip' | 'other' | 'no_payment';
        /**
         * Idempotência (o header `Idempotency-Key` tem prioridade)
         */
        externalId?: string;
        operationNature?: string;
        /**
         * Alias legado de operationNature
         *
         * @deprecated
         */
        nature?: string;
        operationType?: 'outgoing' | 'incoming';
        /**
         * tpImp do XML e orientação do DANFE (1 retrato, 2 paisagem). Omitido: orientação das configurações.
         * `nfeSimplified` (tpImp 3) ainda não é suportado → 422.
         *
         */
        printType?: 'nfeNormalPortrait' | 'nfeNormalLandscape' | 'nfeSimplified';
        /**
         * indFinal. Omitido: 0 quando o destinatário tem IE (indIEDest 1) e 1 para isento (2) ou não contribuinte (9).
         * Não contribuinte (indIEDest 9) sempre sai com indFinal 1 (rejeição 696), mesmo com `normal`.
         *
         */
        consumerType?: 'normal' | 'finalConsumer';
        /**
         * indPres (`outsideEstablishment` = 5, operação presencial fora do estabelecimento)
         */
        presenceType?: 'presential' | 'internet' | 'telephone' | 'delivery' | 'outsideEstablishment' | 'others';
        /**
         * cMunFGIBS (município de consumo do IBS, código IBGE). Só com presenceType outsideEstablishment (indPres 5)
         */
        ibsConsumptionCityCode?: string;
        /**
         * gCompraGov (compras governamentais). entityType tpEnteGov 1–6; reductionRate pRedutor (%) aplicado em pAliqEfet;
         * operationType tpOperGov 1–4 (2 = recebimento do pagamento com fornecimento já realizado: sem ICMS/IPI/PIS/COFINS);
         * previousKeys refDFeAnt (até 99 chaves). Só NF-e.
         *
         */
        governmentPurchase?: {
            entityType: '1' | '2' | '3' | '4' | '5' | '6';
            reductionRate: number;
            operationType: '1' | '2' | '3' | '4';
            previousKeys?: Array<string>;
        };
        /**
         * gPagAntecipado — chaves das NF-e de pagamento antecipado (só NF-e)
         */
        advancePaymentKeys?: Array<string>;
        /**
         * tpRegimeIBSCBS (NT 2026.005 — produção em 14/12/2026). Antes da data → 422
         */
        ibsCbsRegime?: '1' | '2' | '3' | '4';
        /**
         * Inscrição estadual da empresa (multi-IE) usada como emit/IE. Precisa existir no cadastro e ser da UF do emitente;
         * IE de outra UF → 422 (use `stStateRegistrationId` para o IEST).
         *
         */
        stateRegistrationId?: string;
        /**
         * IEST — inscrição de substituto tributário da empresa na UF de destino (cadastrada em inscrições estaduais).
         * Sai em emit/IEST, logo após a IE. Precisa ser da UF do destinatário e diferente da UF do emitente → senão 422.
         *
         */
        stStateRegistrationId?: string;
        cfop?: string;
        issueDate?: string;
        /**
         * Grupo ide (campos avançados). Aceita os aliases SEFAZ finNFe, NFref e refNFe
         */
        ide?: {
            /**
             * finNFe 1–6. `credit` (5, nota de crédito): operationType incoming, `creditType` 01–06 e, nos tipos 01/03/04,
             * exatamente uma referência. `debit` (6, nota de débito): saída, `debitType` 01–08. Nessas notas o Emitfy omite
             * ICMS/IPI/II/PIS/COFINS (B25-80; exceções crédito 03/04/06 e débito 07; débito 06 mantém IPI e, até 2026, PIS/COFINS),
             * exige `items[].ibsCbs` e recusa os grupos detalhados `icms`, `ipi`, `importTax` e `icmsUfDest`.
             *
             */
            purpose?: 'normal' | 'complementary' | 'adjustment' | 'return' | 'credit' | 'debit';
            /**
             * tpNFCredito (alias SEFAZ tpNFCredito)
             */
            creditType?: string;
            /**
             * tpNFDebito (alias SEFAZ tpNFDebito)
             */
            debitType?: string;
            /**
             * Chaves de NF-e referenciadas (NFref/refNFe). Com purpose ≠ normal, informe referencedKeys ou references
             */
            referencedKeys?: Array<string>;
            /**
             * Documentos referenciados (NFref) de qualquer tipo, discriminados por `type`:
             * `nfe` (refNFe) e `cte` (refCTe) com `key` de 44 dígitos; `nf` (refNF, modelo 01/02) e `producer`
             * (refNFP, nota de produtor modelo 01/04, com `stateRegistration`) com state (UF ou código IBGE),
             * yearMonth (AAMM, AAAAMM ou AAAA-MM), taxId, model, series (0–999) e number; `ecf` (refECF, cupom
             * fiscal modelo 2B/2C/2D) com ecfNumber (1–3 dígitos) e cooNumber (1–6 dígitos).
             *
             */
            references?: Array<{
                type: 'nfe' | 'cte' | 'nf' | 'producer' | 'ecf';
                /**
                 * nfe/cte
                 */
                key?: string;
                /**
                 * nf/producer: UF ou código IBGE (cUF)
                 */
                state?: string;
                /**
                 * nf/producer: AAMM da emissão
                 */
                yearMonth?: string;
                /**
                 * nf: CNPJ; producer: CNPJ ou CPF
                 */
                taxId?: string;
                /**
                 * producer: IE do produtor ou ISENTO
                 */
                stateRegistration?: string;
                /**
                 * nf: 01/02; producer: 01/04; ecf: 2B/2C/2D
                 */
                model?: string;
                /**
                 * nf/producer: série (0–999)
                 */
                series?: string;
                /**
                 * nf/producer: número
                 */
                number?: number;
                /**
                 * ecf: nECF (número de ordem do ECF)
                 */
                ecfNumber?: string;
                /**
                 * ecf: nCOO
                 */
                cooNumber?: string;
            }>;
            /**
             * dhSaiEnt (data/hora de saída ou entrada)
             */
            departureAt?: string;
            /**
             * cNF (8 dígitos
             */
            randomCode?: string;
            /**
             * idDest é calculado pelas UFs; valor divergente ou `international` → 422
             */
            destinationType?: 'internal' | 'interstate' | 'international';
            /**
             * `1`/`normal`. `6`/`svcAn` (SVC-AN) e `7`/`svcRs` (SVC-RS) só com a flag `NFE_SVC_CONTINGENCY_ENABLED`
             * (senão 422); a UF do emitente precisa usar aquele SVC. O XML sai com tpEmis/dhCont/xJust, mas a
             * transmissão ao autorizador de contingência ainda não existe — a nota fica com erro de validação.
             *
             */
            emissionType?: string;
            /**
             * Não configurável → 422
             */
            process?: string;
            /**
             * Não configurável → 422
             */
            versionProcess?: string;
            /**
             * dhCont — obrigatório com emissionType 6/7; não pode estar no futuro
             */
            contingencyStartedAt?: string;
            /**
             * xJust — obrigatório com emissionType 6/7
             */
            contingencyReason?: string;
        };
        avulsa?: {
            [key: string]: unknown;
        };
        /**
         * Local de retirada (TLocal). IE é obrigatória pela NT 2026.007 para contribuinte (aceita "ISENTO");
         * address exige street, number, district, city, state e cityCode (IBGE, 7 dígitos). Sem address.country, sai Brasil (1058).
         *
         */
        retirada?: {
            /**
             * CPF ou CNPJ
             */
            taxId?: string;
            name?: string;
            /**
             * IE do local (2 a 14 dígitos) ou ISENTO
             */
            stateRegistration?: string;
            /**
             * fone (6 a 14 dígitos)
             */
            phone?: string;
            email?: string;
            address?: DfeAddressLayout;
        };
        /**
         * Local de entrega (TLocal). IE é obrigatória pela NT 2026.007 para contribuinte (aceita "ISENTO");
         * address exige street, number, district, city, state e cityCode (IBGE, 7 dígitos). Sem address.country, sai Brasil (1058).
         *
         */
        entrega?: {
            /**
             * CPF ou CNPJ
             */
            taxId?: string;
            name?: string;
            /**
             * IE do local (2 a 14 dígitos) ou ISENTO
             */
            stateRegistration?: string;
            /**
             * fone (6 a 14 dígitos)
             */
            phone?: string;
            email?: string;
            address?: DfeAddressLayout;
        };
        autXml?: Array<DfeAutXml>;
        /**
         * Cobrança (`cobr/fat` + `dup`). Faltando nFat/vOrig/vLiq, são completados pelas duplicatas e pelo vNF
         */
        billing?: {
            /**
             * nFat
             */
            invoiceNumber?: string;
            /**
             * vOrig
             */
            originalAmount?: number;
            /**
             * vDesc da fatura (netAmount = originalAmount − discount)
             */
            discount?: number;
            /**
             * vLiq
             */
            netAmount?: number;
            duplicates?: Array<{
                /**
                 * nDup
                 */
                number?: string;
                /**
                 * dVenc (AAAA-MM-DD)
                 */
                dueOn?: string;
                /**
                 * vDup
                 */
                amount: number;
            }>;
            /**
             * Atalho das parcelas: gera `dup` numeradas 001, 002… e a fatura (nFat/vOrig/vLiq pelo vNF).
             * Não combina com `duplicates`; a soma não pode passar do vNF (422).
             *
             */
            installments?: Array<{
                /**
                 * dVenc (AAAA-MM-DD)
                 */
                dueOn: string;
                /**
                 * vDup
                 */
                amount: number;
            }>;
        };
        /**
         * Pagamentos detalhados (`pag/detPag`, um por item). A soma (exceto method 90) não pode ser menor que o vNF (422).
         * Excedente vira troco (`vTroco`) automaticamente. Cartão (03/04) e PIX (17) levam o grupo `card` (tpIntegra 2).
         *
         */
        payments?: Array<{
            /**
             * Código tPag SEFAZ (01, 02, 03, 04, 05, 10, 11, 12, 13, 15, 16, 17, 18, 19, 20, 21, 22, 90, 91, 99) ou credit_card, debit_card, pix, bank_transfer, cash, bank_slip, other, no_payment
             */
            method?: string;
            /**
             * vPag (0 com method 90)
             */
            amount: number;
            /**
             * indPag: 0 à vista (padrão), 1 a prazo
             */
            indicator?: '0' | '1';
            /**
             * xPag (padrão "Outros" com method 99)
             */
            description?: string;
            /**
             * tBand: visa, mastercard, amex, elo, hipercard… ou o código de 2 dígitos
             */
            cardBrand?: string;
            /**
             * cAut
             */
            authorization?: string;
            /**
             * CNPJ da credenciadora (14 dígitos)
             */
            cardTaxId?: string;
            /**
             * tpIntegra: 1/integrated/tef (TEF ou Pix dinâmico integrado) ou 2/notIntegrated/pos (padrão)
             */
            integration?: string;
            /**
             * CNPJReceb — CNPJ do beneficiário do pagamento (14 dígitos)
             */
            receiverTaxId?: string;
            /**
             * idTermPag — identificador do terminal/POS
             */
            terminalId?: string;
            /**
             * dPag (AAAA-MM-DD)
             */
            paidOn?: string;
            /**
             * CNPJPag — CNPJ do pagador/transacional (14 dígitos
             */
            payerTaxId?: string;
            /**
             * UFPag (junto com payerTaxId)
             */
            payerState?: string;
        }>;
        /**
         * Troco (vTroco). Opcional; quando enviado precisa ser soma(payments) − vNF. Só com `payments`
         */
        change?: number;
        intermediary?: {
            [key: string]: unknown;
        };
        additional?: {
            /**
             * infCpl (somado às observações padrão)
             */
            complement?: string;
            /**
             * infAdFisco
             */
            fisco?: string;
            /**
             * obsCont
             */
            taxpayerNotes?: Array<{
                /**
                 * xCampo
                 */
                field: string;
                /**
                 * xTexto
                 */
                text: string;
            }>;
            /**
             * obsFisco
             */
            fiscoNotes?: Array<{
                /**
                 * xCampo
                 */
                field: string;
                /**
                 * xTexto
                 */
                text: string;
            }>;
            /**
             * procRef — processo referenciado (NF-e e NFC-e)
             */
            processReferences?: Array<{
                /**
                 * nProc
                 */
                number: string;
                /**
                 * indProc
                 */
                origin: '0' | '1' | '2' | '3' | '4' | '9';
                /**
                 * tpAto
                 */
                actType?: '08' | '10' | '12' | '14' | '15';
            }>;
        };
        export?: {
            [key: string]: unknown;
        };
        purchase?: {
            [key: string]: unknown;
        };
        sugarcane?: {
            [key: string]: unknown;
        };
        /**
         * Na NF-e, csrtId/csrtHash ainda não são suportados → 422
         */
        techResponsible?: DfeTechResponsible;
        nffRequest?: string;
        /**
         * agropecuario (PL_010h) — `defensives` (até 20: number = nReceituario, taxId = CPF do responsável técnico)
         * OU `transitGuide` (type 1–7, state, series?, number até 9 dígitos), nunca os dois. `amount` (qApl) não existe no leiaute → 422
         *
         */
        farming?: {
            [key: string]: unknown;
        };
        /**
         * Totais da nota rateados pelos itens (proporcional ao valor). Se algum item informar o mesmo campo,
         * a soma dos itens prevalece e `totals` precisa bater (422).
         *
         */
        totals?: {
            /**
             * vDesc da nota
             */
            discount?: number;
            /**
             * vSeg da nota
             */
            insurance?: number;
            /**
             * vOutro da nota
             */
            other?: number;
            /**
             * Frete da nota (igual a transport.value; divergência → 422)
             */
            freight?: number;
        };
    };
    headers?: {
        'Idempotency-Key'?: string;
    };
    path: {
        /**
         * UUID da empresa na Emitfy (campo `id` de `GET /companies`). Não é o CNPJ — CNPJ no path retorna 400 `INVALID_COMPANY_ID`.
         *
         */
        companyId: string;
    };
    query?: never;
    url: '/companies/{companyId}/nfe';
};

